\end{eqnarray}

where $\varphi (\cdot )\in L_{\mathcal{F}}^{2}(0,T;\dbR),$ $A,B$ are
deterministic and bounded functions such that

\begin{eqnarray}\label{6.2}
T\int_{0}^{T}\int_{0}^{T}\int_{0}^{s\wedge t}|\widehat{B}
(t,r)B(s,r)|^{2}drdsdt<\frac{R^{2}}{3}.
\end{eqnarray}

Here we denote by
\begin{eqnarray}\label{6.3}
&&\widehat{B}(t,r)=B(t,r)+\int_{r}^{t}P_0(t,v)B(v,r)dv,\quad
t,v\in[0,T],\nonumber\\
&&P_0(t,v) =\sum\limits_{k=1}^{\infty}\Lambda^{k}(t,v), \quad \Lambda^{1}(t,t) =A(t,v), \quad
\Lambda^{k+1}(t,v)=\int_{v}^{t}A(t,r)\Lambda^{k}(r,v)dr .
\end{eqnarray}

Then (\ref{6.1}) admits a unique solution $x(\cdot)\in L_{
\mathcal{F}}^{2}(0,T;\dbR)$ satisfying
\begin{eqnarray}\label{6.4}
\dbE\int_{0}^{T}|x(s)|^{2}ds\leq 6\dbE\int_{0}^{T}|\widehat{\varphi}(s)|^{2}ds,
\end{eqnarray}
where
\begin{eqnarray*}
\widehat{\varphi }(t) &=&\varphi (t)+\int_{0}^{t}P_0(t,s)\varphi
(s)ds,\quad t\in[0,T].
\end{eqnarray*}

